import java.util.*;

public class Main {
    interface Policy { void added(String k); void accessed(String k); String evict(); }

    static class Fifo implements Policy {
        protected final LinkedList<String> order = new LinkedList<>();
        public void added(String k) { order.addLast(k); }
        public void accessed(String k) { }              // FIFO ignores reads
        public String evict() { return order.removeFirst(); }
    }

    static class Lru extends Fifo {
        @Override public void accessed(String k) { order.remove(k); order.addLast(k); }
    }

    static class Cache {
        final Map<String, Integer> map = new HashMap<>();
        final int cap; final Policy policy; String lastEvicted = "none";
        Cache(int cap, Policy policy) { this.cap = cap; this.policy = policy; }
        Integer get(String k) {
            Integer v = map.get(k);
            if (v != null) policy.accessed(k);
            return v;
        }
        void put(String k, int v) {
            if (map.containsKey(k)) policy.accessed(k);
            else {
                if (map.size() == cap) { lastEvicted = policy.evict(); map.remove(lastEvicted); } // policy picks the victim
                policy.added(k);
            }
            map.put(k, v);
        }
    }

    static void run(String name, Policy p) {
        Cache c = new Cache(2, p);
        c.put("a", 1); c.put("b", 2); c.get("a"); c.put("c", 3);
        System.out.println(name + " evicted=" + c.lastEvicted + " keys=" + String.join(",", new TreeSet<>(c.map.keySet())));
    }

    public static void main(String[] args) {
        run("LRU", new Lru());   // same cache, different policy object
        run("FIFO", new Fifo());
    }
}

