class Fifo:
    def __init__(self):
        self.order = []
    def added(self, k): self.order.append(k)
    def accessed(self, k): pass            # FIFO ignores reads
    def evict(self): return self.order.pop(0)

class Lru(Fifo):
    def accessed(self, k):
        self.order.remove(k)
        self.order.append(k)

class Cache:
    def __init__(self, cap, policy):
        self.map, self.cap, self.policy, self.last = {}, cap, policy, "none"
    def get(self, k):
        if k in self.map:
            self.policy.accessed(k)
            return self.map[k]
        return None
    def put(self, k, v):
        if k in self.map:
            self.policy.accessed(k)
        else:
            if len(self.map) == self.cap:
                self.last = self.policy.evict()   # policy picks the victim
                del self.map[self.last]
            self.policy.added(k)
        self.map[k] = v

def run(name, policy):
    c = Cache(2, policy)
    c.put("a", 1); c.put("b", 2); c.get("a"); c.put("c", 3)
    print(name, "evicted=" + c.last, "keys=" + ",".join(sorted(c.map)))

run("LRU", Lru())    # same cache, different policy object
run("FIFO", Fifo())

