class Fifo {
  constructor() { this.order = []; }
  added(k) { this.order.push(k); }
  accessed(k) {}                       // FIFO ignores reads
  evict() { return this.order.shift(); }
}

class Lru extends Fifo {
  accessed(k) {
    this.order.splice(this.order.indexOf(k), 1);
    this.order.push(k);
  }
}

class Cache {
  constructor(cap, policy) { this.map = new Map(); this.cap = cap; this.policy = policy; this.last = "none"; }
  get(k) {
    if (!this.map.has(k)) return undefined;
    this.policy.accessed(k);
    return this.map.get(k);
  }
  put(k, v) {
    if (this.map.has(k)) this.policy.accessed(k);
    else {
      if (this.map.size === this.cap) { this.last = this.policy.evict(); this.map.delete(this.last); } // policy picks the victim
      this.policy.added(k);
    }
    this.map.set(k, v);
  }
}

function run(name, policy) {
  const c = new Cache(2, policy);
  c.put("a", 1); c.put("b", 2); c.get("a"); c.put("c", 3);
  console.log(name + " evicted=" + c.last + " keys=" + [...c.map.keys()].sort().join(","));
}

