#include <bits/stdc++.h>
using namespace std;

struct Policy {
    virtual void added(const string& k) = 0;
    virtual void accessed(const string& k) = 0;
    virtual string evict() = 0;
    virtual ~Policy() = default;
};

struct Fifo : Policy {
    list<string> order;
    void added(const string& k) override { order.push_back(k); }
    void accessed(const string&) override {}          // FIFO ignores reads
    string evict() override { string k = order.front(); order.pop_front(); return k; }
};

struct Lru : Fifo {
    void accessed(const string& k) override { order.remove(k); order.push_back(k); }
};

struct Cache {
    map<string, int> data; size_t cap; Policy& policy; string last = "none";
    Cache(size_t cap, Policy& p) : cap(cap), policy(p) {}
    void get(const string& k) { if (data.count(k)) policy.accessed(k); }
    void put(const string& k, int v) {
        if (data.count(k)) policy.accessed(k);
        else {
            if (data.size() == cap) { last = policy.evict(); data.erase(last); } // policy picks the victim
            policy.added(k);
        }
        data[k] = v;
    }
};

void run(const string& name, Policy& p) {
    Cache c(2, p);
    c.put("a", 1); c.put("b", 2); c.get("a"); c.put("c", 3);
    string keys;
    for (auto& kv : c.data) keys += (keys.empty() ? "" : ",") + kv.first;   // map is sorted
    cout << name << " evicted=" << c.last << " keys=" << keys << endl;
}

int main() {
    Lru lru; Fifo fifo;
    run("LRU", lru);    // same cache, different policy object
    run("FIFO", fifo);
}

