using System;
using System.Collections.Generic;
using System.Linq;

interface IPolicy { void Added(string k); void Accessed(string k); string Evict(); }

class Fifo : IPolicy {
    protected List<string> order = new List<string>();
    public virtual void Added(string k) { order.Add(k); }
    public virtual void Accessed(string k) { }          // FIFO ignores reads
    public string Evict() { string k = order[0]; order.RemoveAt(0); return k; }
}

class Lru : Fifo {
    public override void Accessed(string k) { order.Remove(k); order.Add(k); }
}

class Cache {
    public Dictionary<string, int> Map = new Dictionary<string, int>();
    int cap; IPolicy policy; public string Last = "none";
    public Cache(int cap, IPolicy p) { this.cap = cap; policy = p; }
    public void Get(string k) { if (Map.ContainsKey(k)) policy.Accessed(k); }
    public void Put(string k, int v) {
        if (Map.ContainsKey(k)) policy.Accessed(k);
        else {
            if (Map.Count == cap) { Last = policy.Evict(); Map.Remove(Last); } // policy picks the victim
            policy.Added(k);
        }
        Map[k] = v;
    }
}

class Program {
    static void Run(string name, IPolicy p) {
        Cache c = new Cache(2, p);
        c.Put("a", 1); c.Put("b", 2); c.Get("a"); c.Put("c", 3);
        Console.WriteLine(name + " evicted=" + c.Last + " keys=" + string.Join(",", c.Map.Keys.OrderBy(x => x).ToArray()));
    }
    static void Main() {
        Run("LRU", new Lru());    // same cache, different policy object
        Run("FIFO", new Fifo());
    }
}

