import java.util.*;

public class Main {
    static class Node { int k, v; Node prev, next; Node(int k, int v) { this.k = k; this.v = v; } }

    static class LRU {
        final int cap; final Map<Integer, Node> map = new HashMap<>();
        final Node head = new Node(0, 0), tail = new Node(0, 0);   // sentinels: no null checks
        int evictions = 0;
        LRU(int cap) { this.cap = cap; head.next = tail; tail.prev = head; }
        void unlink(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }
        void append(Node n) { n.prev = tail.prev; n.next = tail; tail.prev.next = n; tail.prev = n; }
        int get(int k) {
            Node n = map.get(k);
            if (n == null) return -1;
            unlink(n); append(n);                 // touch: most recent goes to the tail
            return n.v;
        }
        void put(int k, int v) {
            Node n = map.get(k);
            if (n != null) { n.v = v; unlink(n); append(n); return; }   // update: touch, never evict
            if (map.size() == cap) { Node old = head.next; unlink(old); map.remove(old.k); evictions++; }
            n = new Node(k, v); map.put(k, n); append(n);
        }
        String order() {
            StringBuilder sb = new StringBuilder();
            for (Node n = head.next; n != tail; n = n.next) sb.append(sb.length() > 0 ? "," : "").append(n.k);
            return sb.toString();
        }
    }

    public static void main(String[] args) {
        LRU c = new LRU(2);                       // every operation is O(1)
        c.put(1, 1); c.put(2, 2);
        System.out.println("get(1)=" + c.get(1));
        c.put(3, 3);                              // evicts key 2
        System.out.println("get(2)=" + c.get(2));
        c.put(1, 10);                             // update must not evict
        System.out.println("get(1)=" + c.get(1));
        System.out.println("get(3)=" + c.get(3));
        System.out.println("order=" + c.order() + " evictions=" + c.evictions);
    }
}

