class LRU {
  constructor(cap) {
    this.cap = cap; this.map = new Map(); this.evictions = 0;
    this.head = new Node(0, 0); this.tail = new Node(0, 0);   // sentinels: no null checks
    this.head.next = this.tail; this.tail.prev = this.head;
  }
  unlink(n) { n.prev.next = n.next; n.next.prev = n.prev; }
  append(n) { n.prev = this.tail.prev; n.next = this.tail; this.tail.prev.next = n; this.tail.prev = n; }
  get(k) {
    const n = this.map.get(k);
    if (!n) return -1;
    this.unlink(n); this.append(n);                // touch: most recent goes to the tail
    return n.v;
  }
  put(k, v) {
    let n = this.map.get(k);
    if (n) { n.v = v; this.unlink(n); this.append(n); return; }   // update: touch, never evict
    if (this.map.size === this.cap) {
      const old = this.head.next; this.unlink(old); this.map.delete(old.k); this.evictions++;
    }
    n = new Node(k, v); this.map.set(k, n); this.append(n);
  }
  order() {
    const out = [];
    for (let n = this.head.next; n !== this.tail; n = n.next) out.push(n.k);
    return out.join(",");
  }
}

