#include <bits/stdc++.h>
using namespace std;

struct Node { int k, v; Node *prev = nullptr, *next = nullptr; Node(int k, int v) : k(k), v(v) {} };

struct LRU {
    int cap, evictions = 0;
    unordered_map<int, Node*> map;
    Node head{0, 0}, tail{0, 0};                       // sentinels: no null checks
    LRU(int cap) : cap(cap) { head.next = &tail; tail.prev = &head; }
    void unlink(Node* n) { n->prev->next = n->next; n->next->prev = n->prev; }
    void append(Node* n) { n->prev = tail.prev; n->next = &tail; tail.prev->next = n; tail.prev = n; }
    int get(int k) {
        auto it = map.find(k);
        if (it == map.end()) return -1;
        unlink(it->second); append(it->second);        // touch: most recent goes to the tail
        return it->second->v;
    }
    void put(int k, int v) {
        auto it = map.find(k);
        if (it != map.end()) { it->second->v = v; unlink(it->second); append(it->second); return; } // update: touch, never evict
        if ((int)map.size() == cap) { Node* old = head.next; unlink(old); map.erase(old->k); delete old; evictions++; }
        Node* n = new Node(k, v); map[k] = n; append(n);
    }
    string order() {
        string s;
        for (Node* n = head.next; n != &tail; n = n->next) s += (s.empty() ? "" : ",") + to_string(n->k);
        return s;
    }
};

int main() {
    LRU c(2);                                          // every operation is O(1)
    c.put(1, 1); c.put(2, 2);
    cout << "get(1)=" << c.get(1) << endl;
    c.put(3, 3);                                       // evicts key 2
    cout << "get(2)=" << c.get(2) << endl;
    c.put(1, 10);                                      // update must not evict
    cout << "get(1)=" << c.get(1) << endl;
    cout << "get(3)=" << c.get(3) << endl;
    cout << "order=" << c.order() << " evictions=" << c.evictions << endl;
}

