using System;
using System.Collections.Generic;
using System.Text;

class Node { public int K, V; public Node Prev, Next; public Node(int k, int v) { K = k; V = v; } }

class LRU {
    int cap; public int Evictions;
    Dictionary<int, Node> map = new Dictionary<int, Node>();
    Node head = new Node(0, 0), tail = new Node(0, 0);     // sentinels: no null checks
    public LRU(int cap) { this.cap = cap; head.Next = tail; tail.Prev = head; }
    void Unlink(Node n) { n.Prev.Next = n.Next; n.Next.Prev = n.Prev; }
    void Append(Node n) { n.Prev = tail.Prev; n.Next = tail; tail.Prev.Next = n; tail.Prev = n; }
    public int Get(int k) {
        Node n;
        if (!map.TryGetValue(k, out n)) return -1;
        Unlink(n); Append(n);                              // touch: most recent goes to the tail
        return n.V;
    }
    public void Put(int k, int v) {
        Node n;
        if (map.TryGetValue(k, out n)) { n.V = v; Unlink(n); Append(n); return; }   // update: touch, never evict
        if (map.Count == cap) { Node old = head.Next; Unlink(old); map.Remove(old.K); Evictions++; }
        n = new Node(k, v); map[k] = n; Append(n);
    }
    public string Order() {
        StringBuilder sb = new StringBuilder();
        for (Node n = head.Next; n != tail; n = n.Next) sb.Append(sb.Length > 0 ? "," : "").Append(n.K);
        return sb.ToString();
    }
}

class Program {
    static void Main() {
        LRU c = new LRU(2);                                // every operation is O(1)
        c.Put(1, 1); c.Put(2, 2);
        Console.WriteLine("get(1)=" + c.Get(1));
        c.Put(3, 3);                                       // evicts key 2
        Console.WriteLine("get(2)=" + c.Get(2));
        c.Put(1, 10);                                      // update must not evict
        Console.WriteLine("get(1)=" + c.Get(1));
        Console.WriteLine("get(3)=" + c.Get(3));
        Console.WriteLine("order=" + c.Order() + " evictions=" + c.Evictions);
    }
}

