import java.util.*;

public class Main {
    static class LFU {
        final int cap; int minFreq = 0;
        final Map<Integer, Integer> vals = new HashMap<>(), freq = new HashMap<>();
        final Map<Integer, LinkedHashSet<Integer>> buckets = new HashMap<>();   // count -> keys, oldest first
        LFU(int cap) { this.cap = cap; }
        void touch(int k) {
            int f = freq.get(k);
            buckets.get(f).remove(k);
            if (buckets.get(f).isEmpty()) { buckets.remove(f); if (minFreq == f) minFreq = f + 1; } // key now lives in f+1
            freq.put(k, f + 1);
            buckets.computeIfAbsent(f + 1, x -> new LinkedHashSet<>()).add(k);
        }
        int get(int k) {
            if (!vals.containsKey(k)) return -1;
            touch(k);
            return vals.get(k);
        }
        void put(int k, int v) {
            if (cap == 0) return;
            if (vals.containsKey(k)) { vals.put(k, v); touch(k); return; }
            if (vals.size() == cap) {                      // evict first key of the minimum bucket
                LinkedHashSet<Integer> b = buckets.get(minFreq);
                int old = b.iterator().next();
                b.remove(old);
                if (b.isEmpty()) buckets.remove(minFreq);
                vals.remove(old); freq.remove(old);
            }
            vals.put(k, v); freq.put(k, 1);
            buckets.computeIfAbsent(1, x -> new LinkedHashSet<>()).add(k);
            minFreq = 1;                                   // a new key always has count 1
        }
    }

    public static void main(String[] args) {
        LFU c = new LFU(2);
        c.put(1, 1); c.put(2, 2);
        System.out.println("get(1)=" + c.get(1));
        c.put(3, 3);                                       // evicts 2 (count 1)
        System.out.println("get(2)=" + c.get(2));
        System.out.println("get(3)=" + c.get(3));
        c.put(4, 4);                                       // tie on count 2: evicts older key 1
        System.out.println("get(1)=" + c.get(1));
        System.out.println("get(3)=" + c.get(3));
        System.out.println("get(4)=" + c.get(4));
        System.out.println("minFreq=" + c.minFreq);
    }
}

code.js:
class LFU {
  constructor(cap) {
    this.cap = cap; this.minFreq = 0;
    this.vals = new Map(); this.freq = new Map();
    this.buckets = new Map();                  // count -> Set of keys, oldest first
  }
  touch(k) {
    const f = this.freq.get(k);
    this.buckets.get(f).delete(k);
    if (this.buckets.get(f).size === 0) {
      this.buckets.delete(f);
      if (this.minFreq === f) this.minFreq = f + 1;   // key now lives in f+1
    }
    this.freq.set(k, f + 1);
    if (!this.buckets.has(f + 1)) this.buckets.set(f + 1, new Set());
    this.buckets.get(f + 1).add(k);
  }
  get(k) {
    if (!this.vals.has(k)) return -1;
    this.touch(k);
    return this.vals.get(k);
  }
  put(k, v) {
    if (this.cap === 0) return;
    if (this.vals.has(k)) { this.vals.set(k, v); this.touch(k); return; }
    if (this.vals.size === this.cap) {         // evict first key of the minimum bucket
      const b = this.buckets.get(this.minFreq);
      const old = b.values().next().value;
      b.delete(old);
      if (b.size === 0) this.buckets.delete(this.minFreq);
      this.vals.delete(old); this.freq.delete(old);
    }
    this.vals.set(k, v); this.freq.set(k, 1);
    if (!this.buckets.has(1)) this.buckets.set(1, new Set());
    this.buckets.get(1).add(k);
    this.minFreq = 1;                          // a new key always has count 1
  }
}

