#include <bits/stdc++.h>
using namespace std;

struct LFU {
    int cap, minFreq = 0;
    unordered_map<int, int> vals, freq;
    unordered_map<int, list<int>> buckets;                    // count -> keys, oldest first
    unordered_map<int, list<int>::iterator> pos;              // key -> its spot in its bucket (O(1) removal)
    LFU(int cap) : cap(cap) {}
    void touch(int k) {
        int f = freq[k];
        buckets[f].erase(pos[k]);
        if (buckets[f].empty()) { buckets.erase(f); if (minFreq == f) minFreq = f + 1; } // key now lives in f+1
        freq[k] = f + 1;
        buckets[f + 1].push_back(k);
        pos[k] = prev(buckets[f + 1].end());
    }
    int get(int k) {
        if (!vals.count(k)) return -1;
        touch(k);
        return vals[k];
    }
    void put(int k, int v) {
        if (cap == 0) return;
        if (vals.count(k)) { vals[k] = v; touch(k); return; }
        if ((int)vals.size() == cap) {                        // evict first key of the minimum bucket
            int old = buckets[minFreq].front();
            buckets[minFreq].pop_front();
            if (buckets[minFreq].empty()) buckets.erase(minFreq);
            vals.erase(old); freq.erase(old); pos.erase(old);
        }
        vals[k] = v; freq[k] = 1;
        buckets[1].push_back(k);
        pos[k] = prev(buckets[1].end());
        minFreq = 1;                                          // a new key always has count 1
    }
};

int main() {
    LFU c(2);
    c.put(1, 1); c.put(2, 2);
    cout << "get(1)=" << c.get(1) << endl;
    c.put(3, 3);                                              // evicts 2 (count 1)
    cout << "get(2)=" << c.get(2) << endl;
    cout << "get(3)=" << c.get(3) << endl;
    c.put(4, 4);                                              // tie on count 2: evicts older key 1
    cout << "get(1)=" << c.get(1) << endl;
    cout << "get(3)=" << c.get(3) << endl;
    cout << "get(4)=" << c.get(4) << endl;
    cout << "minFreq=" << c.minFreq << endl;
}

