using System;
using System.Collections.Generic;

class LFU {
    int cap; public int MinFreq;
    Dictionary<int, int> vals = new Dictionary<int, int>(), freq = new Dictionary<int, int>();
    Dictionary<int, LinkedList<int>> buckets = new Dictionary<int, LinkedList<int>>();   // count -> keys, oldest first
    Dictionary<int, LinkedListNode<int>> node = new Dictionary<int, LinkedListNode<int>>(); // O(1) removal
    public LFU(int cap) { this.cap = cap; }
    void Add(int f, int k) {
        if (!buckets.ContainsKey(f)) buckets[f] = new LinkedList<int>();
        node[k] = buckets[f].AddLast(k);
    }
    void Touch(int k) {
        int f = freq[k];
        buckets[f].Remove(node[k]);
        if (buckets[f].Count == 0) { buckets.Remove(f); if (MinFreq == f) MinFreq = f + 1; } // key now lives in f+1
        freq[k] = f + 1;
        Add(f + 1, k);
    }
    public int Get(int k) {
        if (!vals.ContainsKey(k)) return -1;
        Touch(k);
        return vals[k];
    }
    public void Put(int k, int v) {
        if (cap == 0) return;
        if (vals.ContainsKey(k)) { vals[k] = v; Touch(k); return; }
        if (vals.Count == cap) {                               // evict first key of the minimum bucket
            int old = buckets[MinFreq].First.Value;
            buckets[MinFreq].RemoveFirst();
            if (buckets[MinFreq].Count == 0) buckets.Remove(MinFreq);
            vals.Remove(old); freq.Remove(old); node.Remove(old);
        }
        vals[k] = v; freq[k] = 1;
        Add(1, k);
        MinFreq = 1;                                           // a new key always has count 1
    }
}

