import java.util.*;

public class Main {
    // Simulates a cache of size cap; byFreq=true picks the least frequent victim (ties: oldest use), else the least recent.
    static int simulate(int[] trace, int cap, boolean byFreq) {
        Map<Integer, int[]> cache = new HashMap<>();        // key -> {count, lastUse}
        int hits = 0, time = 0;
        for (int k : trace) {
            time++;
            int[] e = cache.get(k);
            if (e != null) { hits++; e[0]++; e[1] = time; continue; }
            if (cache.size() == cap) {                       // O(cap) scan keeps the demo short
                int victim = -1; int[] best = null;
                for (Map.Entry<Integer, int[]> x : cache.entrySet()) {
                    int[] v = x.getValue();
                    boolean better = best == null
                        || (byFreq ? (v[0] < best[0] || (v[0] == best[0] && v[1] < best[1])) : v[1] < best[1]);
                    if (better) { best = v; victim = x.getKey(); }
                }
                cache.remove(victim);
            }
            cache.put(k, new int[]{1, time});
        }
        return hits;
    }

    public static void main(String[] args) {
        // keys 1 and 2 are hot; 10..13 is a one-off scan; then the hot keys return
        int[] trace = {1, 2, 1, 2, 1, 2, 10, 11, 12, 13, 1, 2, 1, 2};
        System.out.println("trace=" + Arrays.toString(trace) + " cap=3");
        System.out.println("LRU hits=" + simulate(trace, 3, false) + "/" + trace.length);
        System.out.println("LFU hits=" + simulate(trace, 3, true) + "/" + trace.length);
    }
}

