public class Main {
    interface Clock { long now(); }                       // injected so tests control time
    static class ManualClock implements Clock { long t; public long now() { return t; } }

    interface RateLimiter { boolean tryAcquire(); }

    static class TokenBucket implements RateLimiter {
        final long capMilli, ratePerSec; long milli, last; final Clock clock;
        TokenBucket(long cap, long ratePerSec, Clock c) {
            capMilli = cap * 1000; this.ratePerSec = ratePerSec; milli = capMilli; clock = c; last = c.now();
        }
        public boolean tryAcquire() {
            long now = clock.now();
            milli = Math.min(capMilli, milli + (now - last) * ratePerSec);   // integer milli-tokens: no float drift
            last = now;
            if (milli >= 1000) { milli -= 1000; return true; }
            return false;
        }
    }

    static class FixedWindow implements RateLimiter {
        final int limit; final long windowMs; long start = -1; int count; final Clock clock;
        FixedWindow(int limit, long windowMs, Clock c) { this.limit = limit; this.windowMs = windowMs; clock = c; }
        public boolean tryAcquire() {
            long w = clock.now() / windowMs * windowMs;
            if (w != start) { start = w; count = 0; }
            return count < limit && ++count > 0;
        }
    }

    // Factory: callers pick an algorithm by name and never see the classes
    static RateLimiter create(String kind, Clock c) {
        if (kind.equals("token")) return new TokenBucket(3, 1, c);
        return new FixedWindow(2, 1000, c);
    }

    static void demo(String kind, long[] times) {
        ManualClock clock = new ManualClock();
        RateLimiter rl = create(kind, clock);
        for (long t : times) {
            clock.t = t;
            System.out.println(kind + " t=" + t + " " + (rl.tryAcquire() ? "allow" : "deny"));
        }
    }

    public static void main(String[] args) {
        demo("token", new long[]{0, 0, 0, 0, 1000, 1000});
        demo("fixed", new long[]{0, 500, 900, 1000});
    }
}

