import java.util.*;

public class Main {
    static final int LIMIT = 3, WINDOW = 10000;          // 3 requests per 10 seconds (times in ms)

    static int fixedStart = -1, fixedCount = 0;
    static boolean fixed(int t) {                        // O(1) memory: one counter per window
        int w = t / WINDOW * WINDOW;
        if (w != fixedStart) { fixedStart = w; fixedCount = 0; }
        if (fixedCount < LIMIT) { fixedCount++; return true; }
        return false;
    }

    static final Deque<Integer> log = new ArrayDeque<>();
    static boolean slidingLog(int t) {                   // exact, but stores up to LIMIT timestamps
        while (!log.isEmpty() && log.peekFirst() <= t - WINDOW) log.pollFirst();   // forget old requests
        if (log.size() < LIMIT) { log.addLast(t); return true; }                   // denied requests are not logged
        return false;
    }

    public static void main(String[] args) {
        int[] times = {9000, 9500, 9900, 10000, 10100, 10200, 10300};
        int f = 0, l = 0;
        for (int t : times) {
            boolean a = fixed(t), b = slidingLog(t);
            if (a) f++;
            if (b) l++;
            System.out.println("t=" + t + " fixed=" + (a ? "allow" : "deny") + " log=" + (b ? "allow" : "deny"));
        }
        System.out.println("allowed fixed=" + f + " log=" + l);
    }
}

