using System;

interface IClock { long Now(); }
class ManualClock : IClock { public long T; public long Now() { return T; } }

class TokenBucket {
    long capMilli, rate, milli, last; IClock clock;
    public TokenBucket(long cap, long ratePerSec, IClock c) { capMilli = cap * 1000; rate = ratePerSec; milli = capMilli; clock = c; last = c.Now(); }
    public bool TryAcquire() {
        long now = clock.Now();
        milli = Math.Min(capMilli, milli + (now - last) * rate);   // integers: boundaries are exact
        last = now;
        if (milli >= 1000) { milli -= 1000; return true; }
        return false;
    }
}

class Program {
    static void Check(string name, bool ok) { Console.WriteLine((ok ? "PASS " : "FAIL ") + name); }

    static void Main() {
        ManualClock clock = new ManualClock();               // no sleep: the test sets the time itself
        TokenBucket b = new TokenBucket(2, 1, clock);        // capacity 2, refill 1 token per second
        bool first = b.TryAcquire(), second = b.TryAcquire();
        Check("burst of 2 allowed", first && second);
        Check("third denied at t=0", !b.TryAcquire());
        clock.T = 999;
        Check("denied at t=999", !b.TryAcquire());           // boundary: one ms before the refill
        clock.T = 1000;
        Check("allowed at t=1000", b.TryAcquire());          // boundary: exactly one token back
        clock.T = 5000;
        int allowed = 0;
        for (int i = 0; i < 5; i++) if (b.TryAcquire()) allowed++;
        Check("refill capped at capacity", allowed == 2);
    }
}

