from bisect import bisect_left, bisect_right

class Room:
    def __init__(self):
        self.starts, self.ends = [], []          # parallel lists sorted by start, half-open [start, end)

    def book(self, s, e):
        """O(log n) search: only the floor and ceiling neighbours can clash."""
        i = bisect_right(self.starts, s) - 1     # floor: latest start <= s
        if i >= 0 and self.ends[i] > s:
            return self._clash(s, e, i)
        j = bisect_left(self.starts, s)          # ceiling: first start >= s
        if j < len(self.starts) and self.starts[j] < e:
            return self._clash(s, e, j)
        self.starts.insert(j, s)
        self.ends.insert(j, e)
        return "[%d,%d) booked" % (s, e)

    def _clash(self, s, e, k):
        return "[%d,%d) rejected: clashes with [%d,%d)" % (s, e, self.starts[k], self.ends[k])

room = Room()
for s, e in [(9, 10), (11, 12), (10, 11), (9, 11), (10, 12), (12, 13), (8, 9), (7, 9)]:
