class Room {
  constructor() { this.starts = []; this.ends = []; }     // parallel arrays sorted by start, half-open [start, end)

  upper(x) {                                              // first index with start > x (binary search)
    let lo = 0, hi = this.starts.length;
    while (lo < hi) { const m = (lo + hi) >> 1; if (this.starts[m] <= x) lo = m + 1; else hi = m; }
    return lo;
  }
  lower(x) {                                              // first index with start >= x
    let lo = 0, hi = this.starts.length;
    while (lo < hi) { const m = (lo + hi) >> 1; if (this.starts[m] < x) lo = m + 1; else hi = m; }
    return lo;
  }

  // O(log n) search: only the floor and ceiling neighbours can clash
  book(s, e) {
    const i = this.upper(s) - 1;                          // floor: latest start <= s
    if (i >= 0 && this.ends[i] > s) return this.clash(s, e, i);
    const j = this.lower(s);                              // ceiling: first start >= s
    if (j < this.starts.length && this.starts[j] < e) return this.clash(s, e, j);
    this.starts.splice(j, 0, s);
    this.ends.splice(j, 0, e);
    return "[" + s + "," + e + ") booked";
  }
  clash(s, e, k) {
    return "[" + s + "," + e + ") rejected: clashes with [" + this.starts[k] + "," + this.ends[k] + ")";
  }
}

