using namespace std;

struct Room {
    map<int, int> byStart;                                  // start -> end, half-open [start, end)

    string clash(int s, int e, map<int, int>::iterator x) {
        return "[" + to_string(s) + "," + to_string(e) + ") rejected: clashes with [" +
               to_string(x->first) + "," + to_string(x->second) + ")";
    }

    // O(log n): only the floor and ceiling neighbours can clash
    string book(int s, int e) {
        auto ceil = byStart.lower_bound(s);                 // first start >= s
        auto up = byStart.upper_bound(s);                   // first start > s; step back for the floor
        if (up != byStart.begin()) {
            auto floor = prev(up);                          // latest start <= s
            if (floor->second > s) return clash(s, e, floor);
        }
        if (ceil != byStart.end() && ceil->first < e) return clash(s, e, ceil);
        byStart[s] = e;
        return "[" + to_string(s) + "," + to_string(e) + ") booked";
    }
};

