using System;
using System.Collections.Generic;

class Room {
    List<int> starts = new List<int>(), ends = new List<int>();   // parallel lists sorted by start, half-open [start, end)

    int Upper(int x) {                                            // first index with start > x (binary search)
        int lo = 0, hi = starts.Count;
        while (lo < hi) { int m = (lo + hi) / 2; if (starts[m] <= x) lo = m + 1; else hi = m; }
        return lo;
    }
    int Lower(int x) {                                            // first index with start >= x
        int lo = 0, hi = starts.Count;
        while (lo < hi) { int m = (lo + hi) / 2; if (starts[m] < x) lo = m + 1; else hi = m; }
        return lo;
    }
    string Clash(int s, int e, int k) {
        return "[" + s + "," + e + ") rejected: clashes with [" + starts[k] + "," + ends[k] + ")";
    }

    // O(log n) search: only the floor and ceiling neighbours can clash
    public string Book(int s, int e) {
        int i = Upper(s) - 1;                                     // floor: latest start <= s
        if (i >= 0 && ends[i] > s) return Clash(s, e, i);
        int j = Lower(s);                                         // ceiling: first start >= s
        if (j < starts.Count && starts[j] < e) return Clash(s, e, j);
        starts.Insert(j, s);
        ends.Insert(j, e);
        return "[" + s + "," + e + ") booked";
    }
}

