import java.util.*;

public class Main {
    record Booking(String series, int day, int start, int end) {}

    static final List<Booking> bookings = new ArrayList<>();

    // RecurrenceRule (daily every N days): expand into occurrence days
    static List<Integer> expand(int firstDay, int everyDays, int count) {
        List<Integer> days = new ArrayList<>();
        for (int i = 0; i < count; i++) days.add(firstDay + i * everyDays);
        return days;
    }

    // All-or-nothing: check every occurrence first, write only if none clashes
    static String bookSeries(String id, int firstDay, int every, int count, int start, int end) {
        List<Integer> days = expand(firstDay, every, count);
        for (int d : days)
            for (Booking b : bookings)
                if (b.day() == d && start < b.end() && b.start() < end) return id + ": rejected, first clash on day " + d;
        for (int d : days) bookings.add(new Booking(id, d, start, end));
        StringJoiner sj = new StringJoiner(",");
        for (int d : days) sj.add(String.valueOf(d));
        return id + ": booked days " + sj;
    }

    public static void main(String[] args) {
        System.out.println(bookSeries("X", 5, 1, 1, 9, 10));      // a single meeting on day 5
        System.out.println(bookSeries("A", 1, 2, 4, 9, 10));      // days 1,3,5,7 hits day 5
        System.out.println(bookSeries("B", 2, 2, 4, 9, 10));      // days 2,4,6,8 is free
        int before = bookings.size();
        bookings.removeIf(b -> b.series().equals("B"));            // series index makes this one pass
        System.out.println("cancel B: removed " + (before - bookings.size()));
        System.out.println("remaining bookings: " + bookings.size());
    }
}

