using namespace std;

struct Booking { string series; int day, start, end; };
vector<Booking> bookings;

// RecurrenceRule: daily every N days
vector<int> expand(int firstDay, int everyDays, int count) {
    vector<int> days;
    for (int i = 0; i < count; i++) days.push_back(firstDay + i * everyDays);
    return days;
}

