using System;
using System.Collections.Generic;

class Booking {
    public string Series; public int Day, Start, End;
    public Booking(string s, int d, int st, int e) { Series = s; Day = d; Start = st; End = e; }
}

class Program {
    static List<Booking> bookings = new List<Booking>();

    // RecurrenceRule: daily every N days
    static List<int> Expand(int firstDay, int everyDays, int count) {
        List<int> days = new List<int>();
        for (int i = 0; i < count; i++) days.Add(firstDay + i * everyDays);
        return days;
    }

    // All-or-nothing: check every occurrence first, write only if none clashes
    static string BookSeries(string id, int firstDay, int every, int count, int start, int end) {
        List<int> days = Expand(firstDay, every, count);
        foreach (int d in days)
            foreach (Booking b in bookings)
                if (b.Day == d && start < b.End && b.Start < end) return id + ": rejected, first clash on day " + d;
        foreach (int d in days) bookings.Add(new Booking(id, d, start, end));
        return id + ": booked days " + string.Join(",", days);
    }

    static void Main() {
        Console.WriteLine(BookSeries("X", 5, 1, 1, 9, 10));      // a single meeting on day 5
        Console.WriteLine(BookSeries("A", 1, 2, 4, 9, 10));      // days 1,3,5,7 hits day 5
        Console.WriteLine(BookSeries("B", 2, 2, 4, 9, 10));      // days 2,4,6,8 is free
        int before = bookings.Count;
        bookings.RemoveAll(b => b.Series == "B");                 // series index makes this one pass
        Console.WriteLine("cancel B: removed " + (before - bookings.Count));
        Console.WriteLine("remaining bookings: " + bookings.Count);
    }
}

