import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    static class Bucket {                                   // frozen clock: no refill, capacity 5
        private int tokens = 5;
        // check-then-act must be one atomic step, so the whole method holds the lock
        synchronized boolean tryAcquire() {
            if (tokens > 0) { tokens--; return true; }
            return false;
        }
    }

    public static void main(String[] args) throws Exception {
        Bucket bucket = new Bucket();
        AtomicInteger allowed = new AtomicInteger();
        Thread[] threads = new Thread[4];
        for (int i = 0; i < threads.length; i++) {
            threads[i] = new Thread(() -> {
                for (int n = 0; n < 5; n++) if (bucket.tryAcquire()) allowed.incrementAndGet();
            });
            threads[i].start();
        }
        for (Thread t : threads) t.join();                  // wait for all, then assert exact totals
        int a = allowed.get();
        System.out.println("threads=4 attempts=20 allowed=" + a + " denied=" + (20 - a));
    }
}

