class Bucket:                                  # frozen clock: no refill, capacity 5
    def __init__(self):
        self.tokens, self.lock = 5, threading.Lock()
    def try_acquire(self):
        with self.lock:                        # check-then-act must be one atomic step
            if self.tokens > 0:
                self.tokens -= 1
                return True
            return False

