const { Worker, isMainThread, workerData } = require("worker_threads");

// Shared memory: slot 0 = tokens left (frozen clock, capacity 5), slot 1 = allowed count
if (isMainThread) {
  const cells = new Int32Array(new SharedArrayBuffer(8));
  cells[0] = 5;
  let done = 0;
  for (let i = 0; i < 4; i++) {
    const w = new Worker(__filename, { workerData: cells });
    w.on("exit", () => {
      if (++done === 4) {                      // wait for all, then assert exact totals
        const a = Atomics.load(cells, 1);
        console.log("threads=4 attempts=20 allowed=" + a + " denied=" + (20 - a));
      }
    });
  }
} else {
  const cells = workerData;
  for (let n = 0; n < 5; n++) {
    for (;;) {                                 // CAS loop: retry if another thread changed the value
      const t = Atomics.load(cells, 0);
      if (t === 0) break;                      // no tokens: deny
      if (Atomics.compareExchange(cells, 0, t, t - 1) === t) { Atomics.add(cells, 1, 1); break; }
    }
  }
}

