using System;
using System.Threading;

class Bucket {                                          // frozen clock: no refill, capacity 5
    int tokens = 5; readonly object gate = new object();
    public bool TryAcquire() {
        lock (gate) {                                   // check-then-act must be one atomic step
            if (tokens > 0) { tokens--; return true; }
            return false;
        }
    }
}

class Program {
    static void Main() {
        Bucket bucket = new Bucket();
        int allowed = 0;
        Thread[] threads = new Thread[4];
        for (int i = 0; i < threads.Length; i++) {
            threads[i] = new Thread(() => {
                for (int n = 0; n < 5; n++) if (bucket.TryAcquire()) Interlocked.Increment(ref allowed);
            });
            threads[i].Start();
        }
        foreach (Thread t in threads) t.Join();         // wait for all, then assert exact totals
        Console.WriteLine("threads=4 attempts=20 allowed=" + allowed + " denied=" + (20 - allowed));
    }
}

