import java.util.*;

public class Main {
    interface Cache { void put(String k, int v); int get(String k); void remove(String k); int size(); }  // -1 means miss

    static class MapCache implements Cache {                // existing class: never edited again
        final Map<String, Integer> m = new HashMap<>();
        public void put(String k, int v) { m.put(k, v); }
        public int get(String k) { return m.getOrDefault(k, -1); }
        public void remove(String k) { m.remove(k); }
        public int size() { return m.size(); }
    }

    static class ManualClock { long t; }

    // New requirement "add TTL": a decorator, so MapCache and any eviction policy stay untouched
    static class TtlCache implements Cache {
        final Cache inner; final ManualClock clock; final long ttl; final Map<String, Long> expiry = new HashMap<>();
        TtlCache(Cache inner, ManualClock clock, long ttl) { this.inner = inner; this.clock = clock; this.ttl = ttl; }
        public void put(String k, int v) { inner.put(k, v); expiry.put(k, clock.t + ttl); }
        public int get(String k) {
            Long e = expiry.get(k);
            if (e != null && e <= clock.t) { inner.remove(k); expiry.remove(k); return -1; }   // lazy expiry
            return inner.get(k);
        }
        public void remove(String k) { inner.remove(k); expiry.remove(k); }
        public int size() { return inner.size(); }
    }

    static String show(int v) { return v == -1 ? "miss" : String.valueOf(v); }

    public static void main(String[] args) {
        ManualClock clock = new ManualClock();
        Cache cache = new TtlCache(new MapCache(), clock, 100);
        cache.put("a", 1);
        System.out.println("t=0 put a=1");
        clock.t = 50;
        System.out.println("t=50 get a -> " + show(cache.get("a")));
        clock.t = 100;
        System.out.println("t=100 get a -> " + show(cache.get("a")));
        System.out.println("inner size=" + cache.size());
    }
}

