#include <bits/stdc++.h>
using namespace std;

struct Cache {                                         // -1 means miss
    virtual void put(const string& k, int v) = 0;
    virtual int get(const string& k) = 0;
    virtual void remove(const string& k) = 0;
    virtual int size() = 0;
    virtual ~Cache() = default;
};

struct MapCache : Cache {                              // existing class: never edited again
    map<string, int> m;
    void put(const string& k, int v) override { m[k] = v; }
    int get(const string& k) override { auto it = m.find(k); return it == m.end() ? -1 : it->second; }
    void remove(const string& k) override { m.erase(k); }
    int size() override { return (int)m.size(); }
};

struct ManualClock { long long t = 0; };

// New requirement "add TTL": a decorator, nothing else changes
struct TtlCache : Cache {
    Cache& inner; ManualClock& clock; long long ttl; map<string, long long> expiry;
    TtlCache(Cache& inner, ManualClock& c, long long ttl) : inner(inner), clock(c), ttl(ttl) {}
    void put(const string& k, int v) override { inner.put(k, v); expiry[k] = clock.t + ttl; }
    int get(const string& k) override {
        auto it = expiry.find(k);
        if (it != expiry.end() && it->second <= clock.t) {    // lazy expiry
            inner.remove(k); expiry.erase(it);
            return -1;
        }
        return inner.get(k);
    }
    void remove(const string& k) override { inner.remove(k); expiry.erase(k); }
    int size() override { return inner.size(); }
};

string show(int v) { return v == -1 ? "miss" : to_string(v); }

