using System;
using System.Collections.Generic;

interface ICache { void Put(string k, int v); int Get(string k); void Remove(string k); int Size(); }   // -1 means miss

class MapCache : ICache {                               // existing class: never edited again
    Dictionary<string, int> m = new Dictionary<string, int>();
    public void Put(string k, int v) { m[k] = v; }
    public int Get(string k) { int v; return m.TryGetValue(k, out v) ? v : -1; }
    public void Remove(string k) { m.Remove(k); }
    public int Size() { return m.Count; }
}

class ManualClock { public long T; }

// New requirement "add TTL": a decorator, nothing else changes
class TtlCache : ICache {
    ICache inner; ManualClock clock; long ttl; Dictionary<string, long> expiry = new Dictionary<string, long>();
    public TtlCache(ICache inner, ManualClock clock, long ttl) { this.inner = inner; this.clock = clock; this.ttl = ttl; }
    public void Put(string k, int v) { inner.Put(k, v); expiry[k] = clock.T + ttl; }
    public int Get(string k) {
        long e;
        if (expiry.TryGetValue(k, out e) && e <= clock.T) {    // lazy expiry
            inner.Remove(k); expiry.Remove(k);
            return -1;
        }
        return inner.Get(k);
    }
    public void Remove(string k) { inner.Remove(k); expiry.Remove(k); }
    public int Size() { return inner.Size(); }
}

class Program {
    static string Show(int v) { return v == -1 ? "miss" : v.ToString(); }

    static void Main() {
        ManualClock clock = new ManualClock();
        ICache cache = new TtlCache(new MapCache(), clock, 100);
        cache.Put("a", 1);
        Console.WriteLine("t=0 put a=1");
        clock.T = 50;
        Console.WriteLine("t=50 get a -> " + Show(cache.Get("a")));
        clock.T = 100;
        Console.WriteLine("t=100 get a -> " + Show(cache.Get("a")));
        Console.WriteLine("inner size=" + cache.Size());
    }
}
